/**
 * Bid Wars content catalog: big categories, each with several subtopics.
 * A round draws 10 items from one subtopic. Items are never shown before they are up for auction.
 * Each subtopic needs at least 10 items; most carry 14–20 so rounds differ.
 */
export type SubtopicDef = { id: string; title: string; subtitle: string; items: string[] };
export type CategoryDef = { id: string; title: string; subtitle: string; accent: string; subtopics: SubtopicDef[]; /** Playable without buying anything. */ free: boolean };

const cat = (id: string, title: string, subtitle: string, accent: string, subtopics: SubtopicDef[], free = false): CategoryDef => ({ id, title, subtitle, accent, subtopics, free });
const sub = (id: string, title: string, subtitle: string, items: string[]): SubtopicDef => ({ id, title, subtitle, items });

